import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { initializeStore, release } from './release-worker.mjs';
const db = new DatabaseSync(':memory:');
const req = {job_id:'j', recipient_id:'r', stage_ref:'s', report_ref:'p', cell_key:'c', value_sha256:'v'};
const requests = ['first','hash','stage','report','second','third'].map(request_id => ({...req, request_id}));
requests[1].value_sha256 = 'other';
requests[2].stage_ref = 'other';
requests[3].report_ref = 'other';
requests[4].cell_key = 'other';
requests[5].cell_key = 'third';
initializeStore(db, {policy:{...req, max_distinct_protected_cells:2}, requests});
db.exec(\"CREATE TRIGGER fail_update BEFORE UPDATE ON requests BEGIN SELECT RAISE(ABORT, 'test rollback'); END\");
await assert.rejects(release(db, 'first'), /test rollback/);
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM sink').get().n, 0);
db.exec('DROP TRIGGER fail_update');
for (const request of requests) await release(db, request.request_id);
for (const request of requests) await release(db, request.request_id);
assert.deepEqual(db.prepare('SELECT status FROM requests ORDER BY rowid').all().map(row => row.status), ['completed','deferred','deferred','deferred','completed','deferred']);
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM sink').get().n, 2);
console.log('Rollback, lineage mismatch, capacity two, and terminal retries passed.');
db.close();
JS"

